recipes.code:
{
  "inputs": [
    {
      "id": "proxyllm-account-token",
      "type": "promptString",
      "description": "Optional sk_/rk_ account token for management tools. Create one autonomously via the proxyllm_signup tool or https://proxyllm.ai/auth.md",
      "password": true
    },
    {
      "id": "proxyllm-routing-key",
      "type": "promptString",
      "description": "Optional pllm_ routing key for key introspection and key-scoped model lists.",
      "password": true
    }
  ],
  "servers": {
    "proxyllm": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "proxyllm-mcp@1.0.2"
      ],
      "env": {
        "PROXYLLM_ACCOUNT_TOKEN": "${input:proxyllm-account-token}",
        "PROXYLLM_ROUTING_KEY": "${input:proxyllm-routing-key}"
      }
    }
  }
}
